  pub const VT_MODEL_VERSION: ::flatbuffers::VOffsetT = 18;
  pub const VT_MODEL_WEIGHTS_SHA256: ::flatbuffers::VOffsetT = 20;
  pub const VT_POOLING_METHOD: ::flatbuffers::VOffsetT = 22;
  pub const VT_TEMPLATE_VERSION: ::flatbuffers::VOffsetT = 24;
