    if let Some(x) = args.TEMPLATE_VERSION { builder.add_TEMPLATE_VERSION(x); }
    if let Some(x) = args.MODEL_WEIGHTS_SHA256 { builder.add_MODEL_WEIGHTS_SHA256(x); }
    if let Some(x) = args.MODEL_VERSION { builder.add_MODEL_VERSION(x); }
    if let Some(x) = args.MODEL_ID { builder.add_MODEL_ID(x); }
    builder.add_DIMENSIONS(args.DIMENSIONS);
    if let Some(x) = args.UPDATE_ID { builder.add_UPDATE_ID(x); }
    if let Some(x) = args.DATASET_ID { builder.add_DATASET_ID(x); }
    builder.add_POOLING_METHOD(args.POOLING_METHOD);
    builder.add_SIMILARITY(args.SIMILARITY);
    builder.add_NORMALIZATION(args.NORMALIZATION);
    builder.add_ENCODING(args.ENCODING);
    builder.finish()
