    let DATASET_ID = self.DATASET_ID().map(|x| {
      alloc::string::ToString::to_string(x)
    });
    let UPDATE_ID = self.UPDATE_ID().map(|x| {
      alloc::string::ToString::to_string(x)
    });
    let DIMENSIONS = self.DIMENSIONS();
    let ENCODING = self.ENCODING();
    let NORMALIZATION = self.NORMALIZATION();
    let SIMILARITY = self.SIMILARITY();
    let MODEL_ID = self.MODEL_ID().map(|x| {
      alloc::string::ToString::to_string(x)
    });
    let MODEL_VERSION = self.MODEL_VERSION().map(|x| {
      alloc::string::ToString::to_string(x)
    });
    let MODEL_WEIGHTS_SHA256 = self.MODEL_WEIGHTS_SHA256().map(|x| {
      alloc::string::ToString::to_string(x)
    });
    let POOLING_METHOD = self.POOLING_METHOD();
    let TEMPLATE_VERSION = self.TEMPLATE_VERSION().map(|x| {
      alloc::string::ToString::to_string(x)
    });
